import math


def calculate(left: float, operator: str, right: float) -> float:
    """Calculate one operation, rejecting invalid operators and zero divisors."""
    if operator == "+":
        return left + right
    if operator == "-":
        return left - right
    if operator == "*":
        return left * right
    if operator == "/":
        if right == 0:
            raise ValueError("Cannot divide by zero.")
        return left / right
    raise ValueError("Choose +, -, *, or /.")


def read_number(prompt: str) -> float:
    """Read a finite number, allowing the user to retry invalid input."""
    while True:
        try:
            number = float(input(prompt))
            if math.isfinite(number):
                return number
        except ValueError:
            pass
        print("Please enter a finite number.")


def format_result(result: float) -> str:
    """Format result with up to 12 significant digits, no scientific notation <1e15, no decimal for whole numbers, and -0 as 0."""
    # Treat negative zero as zero
    if result == 0:
        return "0"
    abs_result = abs(result)
    # Use scientific notation only for very large/small numbers
    if abs_result >= 1e15 or abs_result < 1e-12:
        # Use 12 significant digits in scientific notation
        return f"{result:.12e}"
    # For whole numbers, show as integer
    if result == int(result):
        return str(int(result))
    # For other numbers, show up to 12 significant digits, no scientific notation
    # Use general format with precision 12, but force fixed-point if not scientific
    formatted = f"{result:.12g}"
    # If 'e' in formatted, force fixed-point
    if 'e' in formatted or 'E' in formatted:
        formatted = f"{result:.12f}"
        # Remove trailing zeros and possible trailing decimal point
        formatted = formatted.rstrip('0').rstrip('.')
    return formatted


def main() -> None:
    print("Calculator: +, -, *, / (enter q to quit)")
    try:
        while True:
            operator = input("Operation: ").strip().lower()
            if operator in {"q", "quit", "exit"}:
                break
            if operator not in {"+", "-", "*", "/"}:
                print("Choose +, -, *, or /.")
                continue
            left = read_number("First number: ")
            right = read_number("Second number: ")
            try:
                result = calculate(left, operator, right)
                print(f"Result: {format_result(result)}")
            except ValueError as error:
                print(error)
    except (EOFError, KeyboardInterrupt):
        print()
    print("Goodbye!")


if __name__ == "__main__":
    main()

